<?php defined('ABSPATH')||exit; function bluprint_term_order_register(){ add_submenu_page( 'bluprint-settings', 'ترتیب دسته‌بندی‌ها، برچسب‌ها و برندها', 'ترتیب دسته‌بندی‌ها', 'manage_woocommerce', 'bluprint-term-order', 'bluprint_term_order_admin_page' ); }
add_action('admin_menu','bluprint_term_order_register'); function bluprint_term_order_render_list($parent,$children,$taxonomy){ $items=$children[$parent]??[]; if(!$items)return; echo '<ul class="bp-term-order__list" data-parent-id="'.esc_attr($parent).'">'; foreach($items as $term){ echo '<li data-term-id="'.esc_attr($term->term_id).'">'; echo '<div class="bp-term-order__item">'; echo '<span class="bp-term-order__handle" aria-hidden="true">⠿</span>'; echo '<span class="bp-term-order__name">'.esc_html($term->name).'</span>'; echo '<span class="bp-term-order__count">'.number_format_i18n($term->count).' محصول</span>'; echo '</div>'; if(is_taxonomy_hierarchical($taxonomy))bluprint_term_order_render_list((int)$term->term_id,$children,$taxonomy); echo '</li>'; } echo '</ul>'; }
function bluprint_term_order_admin_page(){ if(!current_user_can('manage_woocommerce'))return; $taxonomies=bluprint_term_order_taxonomies(); $taxonomy=isset($_GET['taxonomy'])?sanitize_key(wp_unslash($_GET['taxonomy'])):'product_cat'; if(!isset($taxonomies[$taxonomy])||!taxonomy_exists($taxonomy))$taxonomy='product_cat'; $terms=bluprint_get_ordered_terms($taxonomy,['hide_empty'=>false]); $children=[]; foreach($terms as $term){ $parent=is_taxonomy_hierarchical($taxonomy)?(int)$term->parent:0; $children[$parent][]=$term; } ?> <div class="wrap bp-term-order"> <h1>مرتب‌سازی اصطلاحات محصولات</h1> <p>برای تغییر ترتیب، هر مورد را با دستگیره آن جابه‌جا کن. دسته‌های فرزند فقط در میان هم‌سطح‌های خودشان قابل جابه‌جایی هستند. تغییرات به‌صورت خودکار ذخیره می‌شوند.</p> <nav class="nav-tab-wrapper"> <?php foreach($taxonomies as $key=>$label):?> <a class="nav-tab <?php echo $taxonomy===$key?'nav-tab-active':'';?>" href="<?php echo esc_url(add_query_arg(['page'=>'bluprint-term-order','taxonomy'=>$key],admin_url('admin.php')));?>"><?php echo esc_html($label);?></a> <?php endforeach;?> </nav> <div class="bp-term-order__panel"> <div class="bp-term-order__header"> <strong><?php echo esc_html($taxonomies[$taxonomy]);?></strong> <span><?php echo number_format_i18n(count($terms));?> مورد</span> </div> <?php if($terms):?> <div id="bp-term-order-root" data-taxonomy="<?php echo esc_attr($taxonomy);?>"> <?php bluprint_term_order_render_list(0,$children,$taxonomy);?> </div> <?php else:?> <p>موردی برای مرتب‌سازی وجود ندارد.</p> <?php endif;?> <div class="bp-term-order__status" role="status" aria-live="polite"></div> </div> </div> <?php }
function bluprint_term_order_admin_assets($hook){ if(!bluprint_is_admin_page('bluprint-term-order'))return; $js='assets/js/admin/term-order.js'; $css='assets/css/admin/term-order.css'; wp_enqueue_script('jquery-ui-sortable'); wp_enqueue_script( 'bluprint-term-order', get_theme_file_uri($js), ['jquery','jquery-ui-sortable'], file_exists(get_theme_file_path($js))?filemtime(get_theme_file_path($js)):null, true ); wp_localize_script('bluprint-term-order','BP_Term_Order',[ 'ajaxUrl'=>admin_url('admin-ajax.php'), 'nonce'=>wp_create_nonce('bluprint_term_order'), 'saving'=>'در حال ذخیره ترتیب...', 'saved'=>'ترتیب با موفقیت ذخیره شد.', 'error'=>'ذخیره ترتیب انجام نشد. دوباره تلاش کنید.' ]); wp_enqueue_style( 'bluprint-term-order', get_theme_file_uri($css), [], file_exists(get_theme_file_path($css))?filemtime(get_theme_file_path($css)):null ); }
add_action('admin_enqueue_scripts','bluprint_term_order_admin_assets'); function bluprint_term_order_save_ajax(){ if(!current_user_can('manage_woocommerce'))wp_send_json_error(['message'=>'دسترسی غیرمجاز.'],403); check_ajax_referer('bluprint_term_order','nonce'); $taxonomy=isset($_POST['taxonomy'])?sanitize_key(wp_unslash($_POST['taxonomy'])):''; $taxonomies=bluprint_term_order_taxonomies(); if(!isset($taxonomies[$taxonomy])||!taxonomy_exists($taxonomy))wp_send_json_error(['message'=>'Taxonomy نامعتبر است.'],400); $parent=isset($_POST['parent'])?absint($_POST['parent']):0; $hierarchical=is_taxonomy_hierarchical($taxonomy); if(!$hierarchical)$parent=0; if($parent){ $parent_term=get_term($parent,$taxonomy); if(!$parent_term||is_wp_error($parent_term))wp_send_json_error(['message'=>'دسته والد نامعتبر است.'],400); } $submitted=isset($_POST['order'])?(array)wp_unslash($_POST['order']):[]; $submitted=array_values(array_unique(array_filter(array_map('absint',$submitted)))); $valid=[]; foreach($submitted as $id){ $term=get_term($id,$taxonomy); if(!$term||is_wp_error($term))continue; if((int)$term->parent!==$parent)continue; $valid[]=$id; } $siblings=get_terms([ 'taxonomy'=>$taxonomy, 'hide_empty'=>false, 'parent'=>$parent, 'fields'=>'ids', 'orderby'=>'name', 'order'=>'ASC' ]); if(is_wp_error($siblings))wp_send_json_error(['message'=>'دریافت اصطلاحات ناموفق بود.'],500); foreach($siblings as $id){ $id=(int)$id; if(!in_array($id,$valid,true))$valid[]=$id; } $orders=get_option('bluprint_term_orders',[]); $orders=is_array($orders)?$orders:[]; $current=$orders[$taxonomy]??[]; if(isset($current[0])&&!is_array($current[0]))$current=[]; $current=is_array($current)?$current:[]; $current[$parent]=$valid; $orders[$taxonomy]=$current; update_option('bluprint_term_orders',$orders,false); wp_send_json_success(['message'=>'ترتیب ذخیره شد.']); }
add_action('wp_ajax_bluprint_save_term_order','bluprint_term_order_save_ajax');